-- CHANGE LOG
-- 1 | maintainer@emeraldcoastsystemsgroup.com | Named local paper books reuse the native paper ledger. The original paper tables remain unchanged; a reset archives their complete rows before clearing the default. No broker accounts or orders.
CREATE TABLE IF NOT EXISTS trading_paper_books (user_sub TEXT NOT NULL, book_ref TEXT NOT NULL, label TEXT NOT NULL, archived BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, PRIMARY KEY (user_sub, book_ref));
CREATE TABLE IF NOT EXISTS trading_paper_book_config (book_ref TEXT NOT NULL, user_sub TEXT NOT NULL, armed BOOLEAN NOT NULL DEFAULT false, posture TEXT NOT NULL DEFAULT 'balanced', starting_cash DOUBLE PRECISION NOT NULL, max_shares INTEGER NOT NULL, max_notional DOUBLE PRECISION NOT NULL, max_orders_per_tick INTEGER NOT NULL, max_quote_age_minutes INTEGER NOT NULL, universe TEXT, armed_at TIMESTAMPTZ, disarmed_at TIMESTAMPTZ, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY (book_ref, user_sub));
CREATE TABLE IF NOT EXISTS trading_paper_book_account (book_ref TEXT NOT NULL, user_sub TEXT NOT NULL, cash DOUBLE PRECISION NOT NULL, equity DOUBLE PRECISION NOT NULL, high_water DOUBLE PRECISION NOT NULL, realized_pl DOUBLE PRECISION NOT NULL DEFAULT 0, starting_cash DOUBLE PRECISION NOT NULL, version INTEGER NOT NULL DEFAULT 0, last_tick_window TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY (book_ref, user_sub));
CREATE TABLE IF NOT EXISTS trading_paper_book_positions (book_ref TEXT NOT NULL, user_sub TEXT NOT NULL, symbol TEXT NOT NULL, qty INTEGER NOT NULL, avg_cost DOUBLE PRECISION NOT NULL, last_price DOUBLE PRECISION, last_price_at TIMESTAMPTZ, peak_price DOUBLE PRECISION, opened_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY (book_ref, user_sub, symbol));
CREATE TABLE IF NOT EXISTS trading_paper_book_orders (book_ref TEXT NOT NULL, order_id TEXT NOT NULL, user_sub TEXT NOT NULL, tick_window TEXT NOT NULL, decision_id TEXT NOT NULL, symbol TEXT NOT NULL, side TEXT NOT NULL, qty INTEGER NOT NULL, fill_price DOUBLE PRECISION NOT NULL, notional DOUBLE PRECISION NOT NULL, reason TEXT NOT NULL, realized_pl DOUBLE PRECISION, status TEXT NOT NULL DEFAULT 'filled', quote_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY (book_ref, user_sub, order_id));
CREATE UNIQUE INDEX IF NOT EXISTS uq_trading_paper_book_orders_window ON trading_paper_book_orders (book_ref, user_sub, tick_window, symbol, side);
CREATE TABLE IF NOT EXISTS trading_paper_book_decisions (book_ref TEXT NOT NULL, decision_id TEXT NOT NULL, user_sub TEXT NOT NULL, tick_window TEXT NOT NULL, symbol TEXT NOT NULL, action TEXT NOT NULL, reason TEXT NOT NULL, score DOUBLE PRECISION, confidence DOUBLE PRECISION, regime DOUBLE PRECISION, rationale TEXT NOT NULL, per_timeframe TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY (book_ref, user_sub, decision_id));
CREATE TABLE IF NOT EXISTS trading_paper_book_ticks (book_ref TEXT NOT NULL, user_sub TEXT NOT NULL, tick_window TEXT NOT NULL, trigger_kind TEXT NOT NULL, run_id TEXT, outcome TEXT NOT NULL, order_count INTEGER NOT NULL DEFAULT 0, equity DOUBLE PRECISION, summary TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY (book_ref, user_sub, tick_window));
CREATE TABLE IF NOT EXISTS trading_paper_book_equity_daily (book_ref TEXT NOT NULL, user_sub TEXT NOT NULL, session_date TEXT NOT NULL, equity DOUBLE PRECISION NOT NULL, cash DOUBLE PRECISION NOT NULL, recorded_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY (book_ref, user_sub, session_date));
